var EXTRA=[{dot:"gray",j:"Orthopadie",h:"Autoinnesto di peroneo lungo per il LCA: effetti su ginocchio e caviglia a 6 mesi",v:"Studio clinico non randomizzato, piccolo e solo maschile: il ginocchio migliora e i punteggi della caviglia non cambiano in modo significativo, con una lieve variazione dell'arco plantare; troppo breve per giudicare il sito donatore. Non è il tuo innesto.",pmid:'42811158',doi:'10.1007/s00132-026-04892-z',temi:["innesto del LCA","peroneo lungo","sito donatore"]},{dot:"gray",j:"Annals of African Medicine",h:"LCM: ricostruzione con semitendinoso reindirizzato, stabilità ripristinata, più complicanze nelle multilegamentose",v:"Coorte prospettica piccola con controllo a un anno: stabilità al valgo e IKDC migliorano in entrambi i gruppi, senza fallimenti dell'innesto; la stabilità è valutata solo con stress in valgo e il campione limita ogni confronto.",pmid:'42813979',doi:'10.4103/aam.aam_692_26',temi:["legamento collaterale mediale","multilegamentose","ricostruzione"]},{dot:"gray",j:"The Knee",h:"Osteotomia derotativa sopramalleolare nel bambino con instabilità rotulea e torsione tibiale",v:"Serie osservazionale a braccio unico con dati raccolti prospetticamente: nessuna lussazione ricorrente dopo l'osteotomia, ma la metà dei casi ha richiesto la rimozione del mezzo di sintesi; piccolo campione e nessun confronto con la sola ricostruzione del MPFL.",pmid:'42815203',doi:'10.1016/j.knee.2026.104644',temi:["MPFL","osteotomia derotativa","instabilità rotulea"]},{dot:"gray",j:"Clinical Biomechanics",h:"Elastografia dopo LCA: il vasto mediale operato resta più morbido",v:"Revisione sistematica di pochi studi di qualità da scarsa a buona: la rigidità ridotta si associa a forza, funzione e atterraggio, e quella del semitendinoso al prelievo; protocolli non standardizzati, associazioni e non cause.",pmid:'42815174',doi:'10.1016/j.clinbiomech.2026.106982',temi:["LCA","riabilitazione","forza del quadricipite"]},{dot:"gray",j:"The Journal of Bone and Joint Surgery",h:"Revisioni di protesi di anca e ginocchio: crescita stimata fino al 2060 in 17 paesi",v:"Modello su dati di registro: le revisioni di ginocchio crescerebbero più di quelle d'anca, con andamenti diversi fra paesi; è una proiezione con ipotesi di tendenza, non un'osservazione.",pmid:'42814846',doi:'10.2106/JBJS.26.00772',temi:["protesi di ginocchio","revisione","registri"]},{dot:"gray",j:"Journal of Robotic Surgery",h:"Protesi totale robotica contro manuale: meno infiammazione al terzo giorno, tempi operatori più lunghi",v:"Coorte retrospettiva di un solo centro con ponderazione per propensione: associazioni precoci su infiammazione e perdita ematica; il significato clinico del rapporto neutrofili-linfociti più alto è incerto e nessun esito a distanza.",pmid:'42814176',doi:'10.1007/s11701-026-04007-y',temi:["protesi robotica","VELYS","esiti precoci"]},{dot:"gray",j:"Orthopaedics & Traumatology: Surgery & Research",h:"Dolore neuropatico dopo protesi totale: screening sistematico e gestione precoce",v:"Studio retrospettivo di un solo chirurgo, senza gruppo di controllo: gli autori stessi dicono che non si può attribuire il recupero al percorso; utile come descrizione dei fattori di rischio.",pmid:'42815686',doi:'10.1016/j.otsr.2026.104914',temi:["protesi di ginocchio","dolore cronico","screening"]},{dot:"gray",j:"Insights into Imaging",h:"MOBCART: un punteggio per la componente ossea dopo ricostruzione osteocondrale, accanto al MOCART 2.0",v:"Studio di riproducibilità su un campione piccolo di RM, con Filardo fra i firmatari: concordanza fra lettori da moderata a buona; non dimostra che il punteggio predica gli esiti clinici.",pmid:'42811246',doi:'10.1186/s13244-026-02404-3',temi:["cartilagine","risonanza magnetica","ricostruzione osteocondrale"]},{dot:"gray",j:"Journal of Experimental Orthopaedics",h:"Concentrato piastrinico liofilizzato nell'artrosi: tre iniezioni contro una",v:"Coorte prospettica con assegnazione non randomizzata: piccolo vantaggio precoce con tre iniezioni, che scompare a tre mesi, più eventi avversi per paziente; vale soprattutto per l'artrosi iniziale e non è un confronto randomizzato.",pmid:'42813099',doi:'10.1002/jeo2.70906',temi:["artrosi","iniezioni intra-articolari","plasma ricco di piastrine"]},{dot:"gray",j:"Arthroscopy Techniques",h:"Cavo del retinacolo rotuleo mediale al posto del legamento quadricipite-femorale, con MPFL",v:"Nota tecnica senza esiti clinici: descrive come ottenere una ricostruzione a doppio fascio con tessuto locale; nessun confronto e nessun dato di risultato.",pmid:'42812676',doi:'10.1002/atn2.70282',temi:["MPFL","instabilità rotulea","nota tecnica"]},{dot:"gray",j:"Cureus",h:"Stretching a basso carico e lunga durata per la rigidità dopo chirurgia attorno al ginocchio",v:"Piccolo studio randomizzato indiano con fisioterapia convenzionale come confronto, quattro settimane: dolore e mobilità migliori nel gruppo con stretching; campione minimo e follow-up brevissimo.",pmid:'42813153',doi:'10.7759/cureus.115430',temi:["rigidità","riabilitazione","mobilità"]},{dot:"gray",j:"Journal of Back and Musculoskeletal Rehabilitation",h:"App per la propriocezione del ginocchio: bassa concordanza con il goniometro digitale",v:"Studio di validità su adulti sani: correlazione bassa con lo strumento di riferimento e affidabilità buona solo in alcuni indici; gli autori avvertono di non generalizzare.",pmid:'42813738',doi:'10.1177/10538127261492775',temi:["propriocezione","app","squat"]},{dot:"gray",j:"Orthopedic Reviews",h:"Protesi totale robotica nei pazienti HIV positivi: una rassegna narrativa",v:"Rassegna narrativa senza studi diretti su questa popolazione: il robot migliora la precisione ma potrebbe aumentare tempo operatorio, infezione e fratture su osso osteoporotico; ipotesi, non dati.",pmid:'42812604',doi:'10.52965/001c.165230',temi:["protesi robotica","HIV","rassegna narrativa"]}];
var SCOPERTE=[{t:"L'intelligenza artificiale in ortopedia va costruita con i chirurghi, non solo per loro",v:"Un editoriale su KSSTA, con Volker Musahl, Stefano Zaffagnini e Michael Hirschmann fra i firmatari, sostiene che i chirurghi devono controllare domanda clinica, dati, validazione e ritiro di ogni strumento, e che conta chi gestisce l'aggiornamento del modello più della sua architettura. Vale la deviazione perché dice chi risponde quando un algoritmo sbaglia; è un'opinione, senza dati nuovi.",pmid:'42811872',doi:'10.1002/ksa.70628',temi:["intelligenza artificiale","chirurgia","responsabilità"]},{t:"Un idrogel d'acido ialuronico che rilascia a lungo un corticosteroide per proteggere la cartilagine",v:"Un gruppo dell'Ospedale affiliato della Xuzhou Medical University (Cina) lega triamcinolone a un idrogel iniettabile che forma un deposito intra-articolare, per evitare i picchi di esposizione che si pensa danneggino la cartilagine; nel topo e nella capra migliora andatura, infiammazione sinoviale e punteggio RM MOCART 2.0. Vale la deviazione perché cambia il modo di pensare l'infiltrazione; è preclinico, e la sicurezza nell'uomo non è dimostrata.",pmid:'42815820',doi:'10.1016/j.actbio.2026.09.049',temi:["bioingegneria","artrosi","infiltrazioni"]},{t:"Onde d'urto contro la rigidità del ginocchio dopo immobilizzazione, con un meccanismo cellulare",v:"Un gruppo di riabilitazione dell'Anhui Medical University (Cina) mostra nel ratto che le onde d'urto riducono la contrattura del ginocchio e la fibrosi della capsula, agendo su ipossia e piroptosi dei fibroblasti. Vale la deviazione perché propone un bersaglio biologico per l'artrofibrosi; è uno studio animale e cellulare, lontano dalla clinica.",pmid:'42811971',doi:'10.31083/FBL52155',temi:["rigidità","onde d'urto","scienza di base"]}];
var SOC={"1": {"video": "Protesi di ginocchio con o senza robot: che cosa dicono i dati? Uno studio sul BMJ ha analizzato il registro nazionale britannico delle protesi: quasi settecentomila interventi fra il 2018 e il 2024, di cui oltre ventiduemila eseguiti con l'aiuto di un robot. Gli autori hanno confrontato quante protesi hanno dovuto essere rioperate nei due gruppi. Per le protesi totali, circa 98,5 protesi su 100 erano ancora al loro posto a cinque anni con la tecnica tradizionale e 98,6 con quella robotica: nessuna differenza nel rischio di rioperazione. Lo stesso vale per le protesi che sostituiscono solo una parte del ginocchio, con un margine di incertezza più ampio. Anche le complicanze durante l'intervento sono simili. Il limite: i pazienti sono stati seguiti in media solo due anni e mezzo, quindi i dati a cinque anni sono una stima. Lo studio osserva i pazienti senza assegnarli a sorte, non distingue i diversi robot e non dice nulla su quanto sia precisa la posizione dell'impianto né su come stiano i pazienti.", "linkedin": "Emulazione di trial su National Joint Registry (Mohammad, Judge, Griffin, Murray; BMJ, settembre 2026): 697.145 sostituzioni di ginocchio 2018-2024, 22.111 robotiche. Esito principale: sopravvivenza dell'impianto a 5 anni (follow-up medio 2,5 anni), abbinamento per punteggio di propensione.\n\nProtesi totale: 98,5% (IC 95% 98,3-98,7) convenzionale contro 98,6% (98,2-99,0) robotica; HR di revisione 1,03 (IC 95% 0,86-1,26; p=0,71). Monocompartimentale: 97,8% (97,2-98,3) contro 96,4% (92,4-98,3); HR 1,03 (IC 95% 0,75-1,42; p=0,86). Nessuna differenza per causa specifica di revisione né per complicanze intraoperatorie.\n\nLimiti: osservazionale, confondimento residuo non escluso; follow-up medio di 2,5 anni, quindi la stima a 5 anni è una proiezione; piattaforme robotiche non distinte nell'abstract; nessun dato su precisione dell'impianto o PROM. Gli autori richiamano la valutazione dei costi di capitale e di procedura.", "instagram": "🦵 Protesi di ginocchio con o senza robot: nel registro britannico (697.145 interventi, BMJ) nessuna differenza nel rischio di rioperare la protesi.\n\nCirca 98,5 protesi totali su 100 senza revisione a cinque anni con la tecnica tradizionale e 98,6 con quella robotica.\n\nPazienti seguiti in media solo due anni e mezzo: il risultato riguarda le revisioni a breve termine.", "pazienti": "Protesi di ginocchio con il robot o senza: cambia qualcosa? Un grande studio inglese, pubblicato sul BMJ, ha confrontato quasi settecentomila protesi di ginocchio impiantate fra il 2018 e il 2024, di cui oltre ventiduemila con l'aiuto di un robot, guardando quante hanno dovuto essere rioperate. Il risultato è che non ci sono differenze: nei due gruppi quasi tutte le protesi, circa 98 su 100, erano ancora al loro posto a cinque anni. Anche le complicanze durante l'intervento sono state simili. Il robot non ha né aumentato né ridotto il bisogno di nuove operazioni. Detto questo, i pazienti sono stati seguiti in media solo due anni e mezzo, e lo studio non dice come si sentano i pazienti né quanto sia precisa la posizione della protesi. Per questo la scelta della tecnica resta una decisione da discutere con il proprio chirurgo, caso per caso."}};
var SOCV={"1": {"video": {"chir": ["Protesi di ginocchio robotica contro convenzionale: che cosa dicono i dati di registro? Uno studio pubblicato sul BMJ ha usato il National Joint Registry di Inghilterra, Galles, Irlanda del Nord e isole: 697.145 sostituzioni di ginocchio dal 2018 al 2024, di cui 22.111 robotiche. Con un'emulazione di trial e abbinamento per punteggio di propensione, gli autori hanno confrontato sopravvivenza dell'impianto e cause di revisione.", "Nelle protesi totali la sopravvivenza stimata a 5 anni è 98,5% con la tecnica convenzionale e 98,6% con la robotica: rischio di revisione con HR 1,03, intervallo di confidenza al 95% da 0,86 a 1,26. Nelle monocompartimentali 97,8% contro 96,4%, HR 1,03, intervallo da 0,75 a 1,42. Cause di revisione e complicanze intraoperatorie non differiscono.", "Il limite principale è il tempo: il follow-up medio è di 2,5 anni, quindi la stima a 5 anni è una proiezione e le revisioni tardive non sono ancora visibili. Il disegno è osservazionale, il confondimento residuo non è escluso, l'abstract non distingue le piattaforme robotiche e non misura precisione dell'impianto né esiti riferiti dal paziente."], "misto": ["Protesi di ginocchio con o senza robot: che cosa dicono i dati? Uno studio sul BMJ ha analizzato il registro nazionale britannico delle protesi: quasi settecentomila interventi fra il 2018 e il 2024, di cui oltre ventiduemila eseguiti con l'aiuto di un robot. Gli autori hanno confrontato quante protesi hanno dovuto essere rioperate nei due gruppi.", "Per le protesi totali, circa 98,5 protesi su 100 erano ancora al loro posto a cinque anni con la tecnica tradizionale e 98,6 con quella robotica: nessuna differenza nel rischio di rioperazione. Lo stesso vale per le protesi che sostituiscono solo una parte del ginocchio, con un margine di incertezza più ampio. Anche le complicanze durante l'intervento sono simili.", "Il limite: i pazienti sono stati seguiti in media solo due anni e mezzo, quindi i dati a cinque anni sono una stima. Lo studio osserva i pazienti senza assegnarli a sorte, non distingue i diversi robot e non dice nulla su quanto sia precisa la posizione dell'impianto né su come stiano i pazienti."], "pazienti": ["Protesi di ginocchio con il robot o senza: cambia qualcosa? Un grande studio inglese, pubblicato sul BMJ, ha confrontato quasi settecentomila protesi di ginocchio impiantate fra il 2018 e il 2024, di cui oltre ventiduemila con l'aiuto di un robot, guardando quante hanno dovuto essere rioperate.", "Il risultato è che non ci sono differenze: nei due gruppi quasi tutte le protesi, circa 98 su 100, erano ancora al loro posto a cinque anni. Anche le complicanze durante l'intervento sono state simili. Il robot non ha né aumentato né ridotto il bisogno di nuove operazioni.", "Detto questo, i pazienti sono stati seguiti in media solo due anni e mezzo, e lo studio non dice come si sentano i pazienti né quanto sia precisa la posizione della protesi. Per questo la scelta della tecnica resta una decisione da discutere con il proprio chirurgo, caso per caso."]}, "linkedin": {"chir": ["Emulazione di trial su National Joint Registry (Mohammad, Judge, Griffin, Murray; BMJ, settembre 2026): 697.145 sostituzioni di ginocchio 2018-2024, 22.111 robotiche. Esito principale: sopravvivenza dell'impianto a 5 anni (follow-up medio 2,5 anni), abbinamento per punteggio di propensione.", "Protesi totale: 98,5% (IC 95% 98,3-98,7) convenzionale contro 98,6% (98,2-99,0) robotica; HR di revisione 1,03 (IC 95% 0,86-1,26; p=0,71). Monocompartimentale: 97,8% (97,2-98,3) contro 96,4% (92,4-98,3); HR 1,03 (IC 95% 0,75-1,42; p=0,86). Nessuna differenza per causa specifica di revisione né per complicanze intraoperatorie.", "Limiti: osservazionale, confondimento residuo non escluso; follow-up medio di 2,5 anni, quindi la stima a 5 anni è una proiezione; piattaforme robotiche non distinte nell'abstract; nessun dato su precisione dell'impianto o PROM. Gli autori richiamano la valutazione dei costi di capitale e di procedura."], "misto": ["Protesi di ginocchio robotica o convenzionale: uno studio sul BMJ (settembre 2026) ha usato il registro nazionale britannico, 697.145 interventi dal 2018 al 2024, di cui 22.111 con il robot, per confrontare quante protesi hanno richiesto una revisione.", "Nelle protesi totali la sopravvivenza dell'impianto a cinque anni è 98,5% con la tecnica convenzionale e 98,6% con la robotica; nelle monocompartimentali 97,8% contro 96,4%, con un intervallo di incertezza più ampio nel gruppo robotico. Nessuna differenza nel rischio di revisione né nelle complicanze durante l'intervento.", "Il limite: follow-up medio di soli due anni e mezzo, studio osservazionale, piattaforme robotiche non distinte e nessun dato su precisione dell'impianto o sul vissuto dei pazienti. Il risultato riguarda le revisioni a breve termine, non l'insieme dei benefici possibili."], "pazienti": ["Protesi di ginocchio con o senza robot: un grande studio inglese su quasi settecentomila interventi (BMJ, settembre 2026) non ha trovato differenze nella probabilità di dover rioperare la protesi.", "Nei due gruppi circa 98 protesi totali su 100 erano ancora al loro posto a cinque anni, e anche le complicanze durante l'intervento sono state simili.", "I pazienti sono stati seguiti in media due anni e mezzo e lo studio non dice come si sentano: la scelta della tecnica resta una decisione da prendere insieme al chirurgo."]}, "instagram": {"chir": ["🦵 Protesi di ginocchio robotica contro convenzionale, registro NJR (BMJ): 697.145 interventi, 22.111 robotici. Sopravvivenza a 5 anni 98,5% contro 98,6% nella protesi totale, HR di revisione 1,03 (IC 95% 0,86-1,26).", "Monocompartimentale: HR 1,03 (IC 95% 0,75-1,42). Nessuna differenza per causa di revisione né per complicanze intraoperatorie.", "Limiti: follow-up medio 2,5 anni, osservazionale, piattaforme non distinte, nessun dato su precisione o PROM."], "misto": ["🦵 Protesi di ginocchio con o senza robot: nel registro britannico (697.145 interventi, BMJ) nessuna differenza nel rischio di rioperare la protesi.", "Circa 98,5 protesi totali su 100 senza revisione a cinque anni con la tecnica tradizionale e 98,6 con quella robotica.", "Pazienti seguiti in media solo due anni e mezzo: il risultato riguarda le revisioni a breve termine."], "pazienti": ["🦵 Protesi di ginocchio con il robot o senza: in un grande studio inglese non ci sono differenze nel bisogno di rioperare la protesi.", "In entrambi i gruppi circa 98 protesi su 100 erano ancora al loro posto a cinque anni.", "Lo studio non dice come si sentano i pazienti: la scelta si discute con il proprio chirurgo."]}, "reel": {"chir": ["[PROTESI ROBOTICA] BMJ, registro NJR: 697.145 sostituzioni di ginocchio, 22.111 robotiche.", "[IL RISULTATO] Protesi totale, HR di revisione 1,03 (IC 95% 0,86-1,26): nessuna differenza.", "[IL LIMITE] Follow-up medio 2,5 anni, osservazionale, piattaforme non distinte."], "misto": ["[PROTESI DI GINOCCHIO] Con il robot o senza? Quasi 700.000 interventi nel registro britannico.", "[IL RISULTATO] Nessuna differenza nel rischio di dover rioperare la protesi.", "[IL LIMITE] Seguiti in media solo due anni e mezzo."], "pazienti": ["[PROTESI DI GINOCCHIO] Con il robot o senza? Un grande studio inglese ha confrontato quasi 700.000 interventi.", "[IL RISULTATO] Quasi tutte le protesi erano ancora al loro posto a cinque anni, in entrambi i gruppi.", "[IL LIMITE] Lo studio non dice come si sentano i pazienti."]}}};
